import { Icon } from "@/components/forge/icon"
import { Spinner } from "@/components/ui/spinner"
import { type ActivityState } from "./lib/activity"
import { cn } from "cn"

export function ActivityMark({ state }: { state: ActivityState }) {
  return (
    <span
      aria-hidden="true"
      className={cn(
        "flex size-5 shrink-0 items-center justify-center rounded-full",
        state === "complete" &&
          "bg-status-success text-status-success-foreground",
        state === "waiting" &&
          "bg-status-running text-status-running-foreground",
        state === "error" && "bg-status-failed text-status-failed-foreground",
        state === "stopped" && "bg-muted text-muted-foreground"
      )}
    >
      {state === "running" ? (
        <Spinner className="size-3.5" />
      ) : (
        <Icon
          icon={
            state === "complete"
              ? "check"
              : state === "stopped"
                ? "stop"
                : "warning"
          }
          size={12}
        />
      )}
    </span>
  )
}

import * as React from "react"
import { useAuiState } from "@assistant-ui/react"
import { useAdkArtifacts } from "@assistant-ui/react-google-adk"
import {
  Copy01Icon,
  Download04Icon,
  FileCodeIcon,
  Tick02Icon,
} from "@hugeicons/core-free-icons"
import Markdown from "react-markdown"
import remarkGfm from "remark-gfm"
import { cn } from "cn"

import "./canvas.css"
import { TooltipIconButton } from "@/components/assistant-ui/elements/tooltip-icon-button"
import { useAssistantSettings } from "@/components/forge/assistant"
import { Icon } from "@/components/forge/icon"
import { SidePanel } from "./side-panel"
import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Skeleton } from "@/components/ui/skeleton"
import { useCopyToClipboard } from "@/hooks/use-copy-to-clipboard"
import { useCanvas } from "./lib/canvas"
import {
  artifactText,
  downloadDocument,
  highlight,
  isMarkdown,
} from "./lib/documents"

type Loaded =
  { key: string; text: string } | { key: string; error: string } | undefined

/**
 * The document the canvas shows, loaded from the chat API's artifacts: the
 * version picked, or the latest, reloaded as the agent saves new versions
 * (`useAdkArtifacts` updates with each save).
 */
function useDocument() {
  const { artifacts: api } = useAssistantSettings()
  const sessionId = useAuiState((s) => s.threadListItem.remoteId)
  const latest = useAdkArtifacts()
  const { filename, version } = useCanvas()
  const latestVersion = filename ? latest[filename] : undefined
  const shown = version ?? latestVersion
  const [versions, setVersions] = React.useState<number[]>([])
  const [loaded, setLoaded] = React.useState<Loaded>()
  const key = `${sessionId}/${filename}/${shown}`

  React.useEffect(() => {
    if (!api || !sessionId || !filename) return
    let current = true
    api
      .listVersions(sessionId, filename)
      .then((list) => current && setVersions(list))
      .catch(() => current && setVersions([]))
    return () => {
      current = false
    }
  }, [api, sessionId, filename, latestVersion])

  React.useEffect(() => {
    if (!api || !sessionId || !filename) return
    let current = true
    api
      .load(sessionId, filename, shown)
      .then((data) => {
        const text = artifactText(data)
        if (!current) return
        setLoaded(
          text === undefined
            ? { key, error: "This file isn't text, so it can't be shown here." }
            : { key, text }
        )
      })
      .catch(
        (error: unknown) =>
          current &&
          setLoaded({
            key,
            error: error instanceof Error ? error.message : String(error),
          })
      )
    return () => {
      current = false
    }
  }, [api, sessionId, filename, shown, key])

  return {
    filename,
    shown,
    latestVersion,
    versions,
    // Only what's loaded for what's picked; the last one while the next loads.
    document: loaded?.key === key ? loaded : undefined,
  }
}

function VersionPicker({
  versions,
  shown,
  latest,
}: {
  versions: number[]
  shown: number | undefined
  latest: number | undefined
}) {
  const showVersion = useCanvas((state) => state.showVersion)
  if (versions.length < 2 || shown === undefined) return null
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            variant="ghost"
            size="xs"
            className="h-7 px-2 text-xs font-normal text-muted-foreground tabular-nums"
          />
        }
        aria-label={`Version ${shown + 1}`}
      >
        v{shown + 1}
        {shown === latest && (
          <span className="text-muted-foreground/60">latest</span>
        )}
        <Icon icon="down" data-icon="inline-end" />
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-40">
        <DropdownMenuGroup>
          <DropdownMenuLabel>Versions</DropdownMenuLabel>
          <DropdownMenuRadioGroup
            value={String(shown)}
            onValueChange={(value) =>
              showVersion(Number(value) === latest ? null : Number(value))
            }
          >
            {[...versions].reverse().map((each) => (
              <DropdownMenuRadioItem
                key={each}
                value={String(each)}
                closeOnClick
              >
                <span className="tabular-nums">v{each + 1}</span>
                {each === latest && (
                  <span className="text-muted-foreground">latest</span>
                )}
              </DropdownMenuRadioItem>
            ))}
          </DropdownMenuRadioGroup>
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

function CodeView({ filename, text }: { filename: string; text: string }) {
  const html = React.useMemo(() => highlight(filename, text), [filename, text])
  const lines = text.split("\n").length
  return (
    <div className="canvas-code flex min-w-max font-mono text-xs leading-5">
      <div
        aria-hidden
        className="sticky start-0 shrink-0 bg-background py-3 ps-3 pe-3 text-end text-muted-foreground/50 tabular-nums select-none"
      >
        {Array.from({ length: lines }, (_, index) => (
          <div key={index}>{index + 1}</div>
        ))}
      </div>
      <pre className="py-3 pe-6 text-foreground">
        <code dangerouslySetInnerHTML={{ __html: html }} />
      </pre>
    </div>
  )
}

function ViewSwitch({
  view,
  onChange,
}: {
  view: "preview" | "source"
  onChange: (view: "preview" | "source") => void
}) {
  return (
    <div className="flex rounded-md bg-muted p-0.5 text-xs">
      {(["preview", "source"] as const).map((each) => (
        <button
          key={each}
          type="button"
          aria-pressed={view === each}
          onClick={() => onChange(each)}
          className="rounded-[5px] px-2 py-0.5 text-muted-foreground capitalize transition-colors aria-pressed:bg-background aria-pressed:text-foreground aria-pressed:shadow-xs"
        >
          {each}
        </button>
      ))}
    </div>
  )
}

/**
 * Beside the chat while `useScreen`'s panel is "canvas": a document the agent
 * saved (write_document), highlighted by its extension, with Markdown
 * previewed; its versions, and copy and download.
 */
export function CanvasPanel() {
  const { filename, shown, latestVersion, versions, document } = useDocument()
  const { isCopied, copyToClipboard } = useCopyToClipboard()
  const [view, setView] = React.useState<"preview" | "source">("preview")
  const text = document && "text" in document ? document.text : undefined
  const markdown = filename ? isMarkdown(filename) : false

  return (
    <SidePanel
      panel="canvas"
      title={<span className="font-mono">{filename ?? "Canvas"}</span>}
      icon={FileCodeIcon}
      className="w-[min(46rem,52vw)] bg-background"
      actions={
        filename && (
          <>
            <VersionPicker
              versions={versions}
              shown={shown}
              latest={latestVersion}
            />
            {markdown && <ViewSwitch view={view} onChange={setView} />}
            <TooltipIconButton
              tooltip={isCopied ? "Copied" : "Copy"}
              side="bottom"
              disabled={text === undefined}
              className="size-7 rounded-md p-0 text-muted-foreground hover:text-foreground"
              onClick={() => text !== undefined && copyToClipboard(text)}
            >
              <Icon icon={isCopied ? Tick02Icon : Copy01Icon} size={14} />
            </TooltipIconButton>
            <TooltipIconButton
              tooltip="Download"
              side="bottom"
              disabled={text === undefined}
              className="size-7 rounded-md p-0 text-muted-foreground hover:text-foreground"
              onClick={() =>
                text !== undefined && downloadDocument(filename, text)
              }
            >
              <Icon icon={Download04Icon} size={14} />
            </TooltipIconButton>
          </>
        )
      }
    >
      <div className={cn("min-h-0 flex-1 overflow-auto", !filename && "p-4")}>
        {!filename ? (
          <p className="text-sm text-muted-foreground">
            Nothing open. When the assistant writes a document or a long piece
            of code, it opens here.
          </p>
        ) : !document ? (
          <div className="flex flex-col gap-2 p-5" aria-busy>
            <Skeleton className="h-4 w-2/3" />
            <Skeleton className="h-4 w-5/6" />
            <Skeleton className="h-4 w-1/2" />
          </div>
        ) : "error" in document ? (
          <p className="p-4 text-sm text-destructive">{document.error}</p>
        ) : markdown && view === "preview" ? (
          <article className="canvas-prose mx-auto max-w-2xl px-6 py-5">
            <Markdown remarkPlugins={[remarkGfm]}>{document.text}</Markdown>
          </article>
        ) : (
          <CodeView filename={filename} text={document.text} />
        )}
      </div>
    </SidePanel>
  )
}

/*
 * The canvas: highlighted code (highlight.js tokens, in the same colours as
 * the rich text editor's) and a Markdown preview.
 */
.canvas-code .hljs-comment,
.canvas-code .hljs-quote {
  color: var(--subtle);
  font-style: italic;
}
.canvas-code .hljs-keyword,
.canvas-code .hljs-selector-tag,
.canvas-code .hljs-meta .hljs-keyword,
.canvas-code .hljs-doctag {
  color: var(--viz-5);
}
.canvas-code .hljs-string,
.canvas-code .hljs-regexp,
.canvas-code .hljs-addition,
.canvas-code .hljs-meta .hljs-string {
  color: var(--diff-added);
}
.canvas-code .hljs-number,
.canvas-code .hljs-literal,
.canvas-code .hljs-symbol,
.canvas-code .hljs-bullet,
.canvas-code .hljs-variable.language_ {
  color: var(--viz-3);
}
.canvas-code .hljs-title,
.canvas-code .hljs-title.function_,
.canvas-code .hljs-section,
.canvas-code .hljs-selector-id {
  color: var(--viz-1);
}
.canvas-code .hljs-type,
.canvas-code .hljs-built_in,
.canvas-code .hljs-title.class_,
.canvas-code .hljs-selector-class {
  color: var(--viz-2);
}
.canvas-code .hljs-attr,
.canvas-code .hljs-attribute,
.canvas-code .hljs-name,
.canvas-code .hljs-tag,
.canvas-code .hljs-property {
  color: var(--viz-4);
}
.canvas-code .hljs-deletion {
  color: var(--diff-removed);
}
.canvas-code .hljs-meta,
.canvas-code .hljs-template-variable {
  color: var(--muted-foreground);
}

.canvas-prose {
  font-size: 0.875rem;
  line-height: 1.7;
  color: var(--foreground);
}
.canvas-prose > * + * {
  margin-top: 0.85em;
}
.canvas-prose h1 {
  font-size: 1.4rem;
  font-weight: 600;
  line-height: 1.3;
}
.canvas-prose h2 {
  margin-top: 1.4em;
  font-size: 1.1rem;
  font-weight: 600;
}
.canvas-prose h3 {
  margin-top: 1.2em;
  font-size: 0.95rem;
  font-weight: 600;
}
.canvas-prose ul,
.canvas-prose ol {
  padding-inline-start: 1.4em;
}
.canvas-prose ul {
  list-style: disc;
}
.canvas-prose ol {
  list-style: decimal;
}
.canvas-prose li + li {
  margin-top: 0.25em;
}
.canvas-prose a {
  text-decoration: underline;
  text-underline-offset: 2px;
}
.canvas-prose blockquote {
  border-inline-start: 2px solid var(--border);
  padding-inline-start: 0.9em;
  color: var(--muted-foreground);
}
.canvas-prose :not(pre) > code {
  border-radius: 4px;
  background: var(--muted);
  padding: 0.1em 0.35em;
  font-size: 0.85em;
}
.canvas-prose pre {
  overflow-x: auto;
  border-radius: var(--radius-soft);
  background: var(--muted);
  padding: 0.8em 1em;
  font-size: 0.8rem;
  line-height: 1.6;
}
.canvas-prose table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.8rem;
}
.canvas-prose th,
.canvas-prose td {
  border-bottom: 1px solid var(--border);
  padding: 0.4em 0.6em;
  text-align: start;
}
.canvas-prose th {
  font-weight: 600;
}
.canvas-prose hr {
  border-color: var(--border);
}

import { useEffect, useMemo, useRef, useState } from "react"
import { useAui, useAuiState } from "@assistant-ui/react"
import { TooltipIconButton } from "@/components/assistant-ui/elements/tooltip-icon-button"
import { Icon } from "@/components/forge/icon"
import {
  Command,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandShortcut,
} from "@/components/ui/command"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogTitle,
} from "@/components/ui/dialog"
import { Spinner } from "@/components/ui/spinner"
import {
  historyExcerpt,
  matchesHistory,
  useChatHistory,
  type HistoryEntry,
} from "./lib/chat-history"
import { useScreen } from "./lib/screen-store"
import type { AgentConnection } from "./lib/use-agent-workspace"

const dateFormat = new Intl.DateTimeFormat(undefined, {
  month: "short",
  day: "numeric",
})

/**
 * A chat-history button for the composer (⌘K / Ctrl+K opens it too): a
 * command palette with New chat and the user's conversations, searched by
 * title and by what was said. Use it as `composerTrailingActions`, wrapped
 * with the connection:
 *
 * ```tsx
 * const History = () => <ChatHistoryPalette adkUrl={url} appName="assistant" userId={id} />
 * ```
 *
 * Pass `shortcut={false}` when the app already uses ⌘K for its own palette.
 */
export function ChatHistoryPalette({
  shortcut = true,
  ...connection
}: AgentConnection & {
  /** Open it with ⌘K / Ctrl+K from anywhere on the page. Default true. */
  shortcut?: boolean
}) {
  const aui = useAui()
  const [open, setOpen] = useState(false)
  const [query, setQuery] = useState("")
  const triggerRef = useRef<HTMLButtonElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)
  const switching = useRef(false)
  const [error, setError] = useState<string | null>(null)
  const [busy, setBusy] = useState(false)
  const history = useChatHistory(open, connection)
  const threadItems = useAuiState((s) => s.threads.threadItems)
  const currentId = useAuiState((s) => s.threadListItem.remoteId)
  const threadLoading = useAuiState((s) => s.threads.isLoading)

  const entries = useMemo(() => {
    const known = new Map(history.entries.map((entry) => [entry.id, entry]))
    for (const item of threadItems) {
      if (!item.remoteId || item.status === "archived") continue
      const entry = known.get(item.remoteId)
      if (entry) {
        if (item.title)
          known.set(item.remoteId, { ...entry, title: item.title })
      } else {
        known.set(item.remoteId, {
          id: item.remoteId,
          title: item.title || "Untitled chat",
          text: "",
          updatedAt: item.lastMessageAt?.getTime()
            ? item.lastMessageAt.getTime() / 1000
            : 0,
        })
      }
    }
    return [...known.values()]
      .sort((a, b) => b.updatedAt - a.updatedAt)
      .filter((entry) => matchesHistory(entry, query))
  }, [history.entries, threadItems, query])

  const changeOpen = (next: boolean) => {
    if (next) {
      setQuery("")
      setError(null)
    }
    setOpen(next)
  }
  useEffect(() => {
    if (!shortcut) return
    const onKey = (event: KeyboardEvent) => {
      if (
        (event.metaKey || event.ctrlKey) &&
        !event.altKey &&
        !event.shiftKey &&
        event.key.toLowerCase() === "k"
      ) {
        event.preventDefault()
        setQuery("")
        setError(null)
        setOpen((value) => !value)
      }
    }
    document.addEventListener("keydown", onKey)
    return () => document.removeEventListener("keydown", onKey)
  }, [shortcut])

  const select = async (id?: string) => {
    if (busy) return
    setBusy(true)
    setError(null)
    try {
      // Use the runtime promise so a failed switch keeps the palette open.
      const runtime = aui.threads.__internal_getAssistantRuntime?.()
      if (runtime) {
        if (id) await runtime.threads.switchToThread(id)
        else await runtime.threads.switchToNewThread()
      } else {
        if (id) aui.threads.switchToThread(id)
        else aui.threads.switchToNewThread()
      }
      useScreen.getState().closePanel()
      switching.current = true
      setOpen(false)
    } catch {
      setError("This chat couldn’t be opened. Try again.")
    } finally {
      setBusy(false)
    }
  }

  const newChatAction = (
    <>
      <CommandGroup>
        <CommandItem
          value="new-chat"
          disabled={busy}
          onSelect={() => void select()}
          className="min-h-11 gap-3 px-3 text-sm"
        >
          <Icon icon="plus" size={17} />
          <span>New chat</span>
          <CommandShortcut className="opacity-0 group-data-[selected=true]/command-item:opacity-100">
            ↵
          </CommandShortcut>
        </CommandItem>
      </CommandGroup>
      {!query.trim() && <div className="mx-2 my-2 h-px bg-border" />}
    </>
  )

  return (
    <>
      <TooltipIconButton
        ref={triggerRef}
        tooltip={shortcut ? "Search chats (⌘K / Ctrl+K)" : "Search chats"}
        aria-label="Search chat history"
        aria-haspopup="dialog"
        aria-expanded={open}
        onClick={() => changeOpen(true)}
        type="button"
        className="size-7 shrink-0 rounded-full text-muted-foreground hover:bg-muted hover:text-foreground"
      >
        <Icon icon="message" size={16} />
      </TooltipIconButton>
      <Dialog open={open} onOpenChange={changeOpen}>
        <DialogContent
          className="top-[12dvh] max-h-[78dvh] translate-y-0 gap-0 overflow-hidden p-0 sm:max-w-[580px]"
          showCloseButton={false}
          initialFocus={inputRef}
          finalFocus={() => {
            if (switching.current) {
              switching.current = false
              return (
                document.querySelector<HTMLTextAreaElement>(
                  'textarea[aria-label="Message input"]'
                ) ?? triggerRef.current
              )
            }
            return triggerRef.current
          }}
        >
          <DialogTitle className="sr-only">Chat history</DialogTitle>
          <DialogDescription className="sr-only">
            Search saved conversations or start a new chat. Use arrow keys to
            navigate and Enter to select.
          </DialogDescription>
          <Command shouldFilter={false} loop className="min-h-0">
            <div className="relative">
              <CommandInput
                ref={inputRef}
                value={query}
                onValueChange={setQuery}
                placeholder="Search chat history…"
                aria-label="Search chat history"
                className="pr-12"
              />
              <button
                type="button"
                aria-label="Close chat history"
                onClick={() => changeOpen(false)}
                className="absolute top-2 right-2 flex size-8 items-center justify-center rounded-md text-muted-foreground hover:bg-muted hover:text-foreground"
              >
                <Icon icon="close" size={15} />
              </button>
            </div>
            <CommandList
              className="max-h-[min(420px,55dvh)] p-2"
              aria-busy={history.loading || busy}
            >
              {!query.trim() && newChatAction}
              <CommandGroup
                heading={query.trim() ? "Matching chats" : "Recent chats"}
              >
                {entries.map((entry) => (
                  <HistoryItem
                    key={entry.id}
                    entry={entry}
                    query={query}
                    current={entry.id === currentId}
                    disabled={busy}
                    onSelect={() => void select(entry.id)}
                  />
                ))}
              </CommandGroup>
              {!entries.length && !(history.loading || threadLoading) && (
                <p
                  role="status"
                  className="px-4 py-8 text-center text-sm text-muted-foreground"
                >
                  {query.trim()
                    ? "No chats match your search."
                    : "Your conversations will appear here."}
                </p>
              )}
              {(history.loading || threadLoading) && (
                <p
                  role="status"
                  className="flex items-center justify-center gap-2 px-4 py-4 text-xs text-muted-foreground"
                >
                  <Spinner className="size-3" />
                  Searching saved chats…
                </p>
              )}
              {query.trim() && newChatAction}
            </CommandList>
            {(history.error || error) && (
              <div
                role="alert"
                className="flex items-center justify-between gap-3 border-t px-4 py-3 text-xs text-danger-foreground"
              >
                <span>{error || history.error}</span>
                {history.error && (
                  <button
                    type="button"
                    onClick={history.retry}
                    className="rounded px-2 py-1 font-medium hover:bg-muted"
                  >
                    Retry
                  </button>
                )}
              </div>
            )}
            <div className="flex items-center gap-4 border-t px-4 py-2.5 text-2xs text-muted-foreground">
              <span>↑↓ Navigate</span>
              <span>↵ Open</span>
              <span className="ml-auto">Esc Close</span>
            </div>
          </Command>
        </DialogContent>
      </Dialog>
    </>
  )
}

function HistoryItem({
  entry,
  query,
  current,
  disabled,
  onSelect,
}: {
  entry: HistoryEntry
  query: string
  current: boolean
  disabled: boolean
  onSelect: () => void
}) {
  const excerpt = historyExcerpt(entry, query)
  return (
    <CommandItem
      value={`chat:${entry.id}`}
      disabled={disabled}
      onSelect={onSelect}
      className="min-h-12 gap-3 px-3 py-2.5"
    >
      <Icon icon="message" size={16} className="text-muted-foreground" />
      <span className="min-w-0 flex-1">
        <span className="block truncate text-sm">{entry.title}</span>
        {excerpt && (
          <span className="mt-1 block truncate text-xs text-muted-foreground">
            {excerpt}
          </span>
        )}
      </span>
      <CommandShortcut className="shrink-0 text-2xs tracking-normal">
        {current
          ? "Current"
          : entry.updatedAt > 0
            ? dateFormat.format(new Date(entry.updatedAt * 1000))
            : ""}
      </CommandShortcut>
    </CommandItem>
  )
}

import { useAssistantSettings } from "@/components/forge/assistant"
import { composerChip } from "@/components/forge/assistant"
import { StatsList } from "./stats-list"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import type { AgentModel } from "./lib/assistant-models"
import { exactTokens, usd } from "./lib/format"
import { useTurnStats, useTurnStatsSync } from "./lib/turn-stats"
import { cn } from "cn"

const percent = (fraction: number) =>
  `${(fraction * 100).toFixed(fraction < 0.01 ? 2 : 1)}%`

const RADIUS = 6
const CIRCUMFERENCE = 2 * Math.PI * RADIUS

/** A ring filled to `fraction`, amber past 70% and red past 90%. */
function Ring({ fraction }: { fraction: number }) {
  const filled = Math.min(Math.max(fraction, 0), 1)
  return (
    <svg viewBox="0 0 16 16" className="size-3.5 -rotate-90" aria-hidden>
      <circle
        cx="8"
        cy="8"
        r={RADIUS}
        fill="none"
        strokeWidth="2.5"
        className="stroke-muted-foreground/20"
      />
      <circle
        cx="8"
        cy="8"
        r={RADIUS}
        fill="none"
        strokeWidth="2.5"
        strokeLinecap="round"
        strokeDasharray={CIRCUMFERENCE}
        strokeDashoffset={CIRCUMFERENCE * (1 - filled)}
        className={cn(
          "transition-[stroke-dashoffset] duration-500",
          filled > 0.9
            ? "stroke-destructive"
            : filled > 0.7
              ? "stroke-warning-foreground"
              : "stroke-foreground/70"
        )}
      />
    </svg>
  )
}

/**
 * In the composer: how full the model's context window is (the last model
 * call's input and output against the chosen model's window) and what the
 * conversation has cost so far. It also keeps the conversation's stats read
 * (`useTurnStatsSync`) for the replies' `MessageStats`.
 */
export function ContextMeter({
  adkUrl,
  appName,
  userId,
  catalog,
  defaultModel,
}: {
  adkUrl: string | undefined
  appName: string
  userId: string
  catalog: AgentModel[]
  defaultModel: string | undefined
}) {
  useTurnStatsSync(adkUrl, appName, userId, catalog, defaultModel)
  const stats = useTurnStats((state) => state.stats)
  const chosen = useAssistantSettings().modelSettings?.model ?? defaultModel
  const model = catalog.find((each) => each.id === chosen)
  if (!stats || !model || stats.contextTokens === 0) return null
  const fraction = stats.contextTokens / model.contextWindow
  const turns = Object.values(stats.turns).filter((turn) => turn.calls > 0)
  const calls = turns.reduce((sum, turn) => sum + turn.calls, 0)

  return (
    <TooltipProvider>
      <Tooltip>
        <TooltipTrigger
          render={
            <span
              tabIndex={0}
              data-slot="context-meter"
              className={cn(
                composerChip,
                "inline-flex shrink-0 cursor-default items-center text-xs whitespace-nowrap tabular-nums outline-none"
              )}
            />
          }
          aria-label={`Context ${Math.round(fraction * 100)}% full`}
        >
          <Ring fraction={fraction} />
          {/* The cost when the model has prices; how full, otherwise. The
              exact tokens are in the tooltip. */}
          {/* Just the ring when the chat is narrow; the numbers are in the tooltip. */}
          <span className="text-foreground @max-[36rem]:hidden">
            {stats.cost > 0 ? usd(stats.cost) : percent(fraction)}
          </span>
        </TooltipTrigger>
        <TooltipContent side="top" className="flex-col items-stretch">
          <StatsList
            rows={[
              ["Context", `${percent(fraction)} full`],
              ["Used", exactTokens(stats.contextTokens)],
              ["Window", exactTokens(model.contextWindow)],
              ["Model", model.name],
              ["Turns", turns.length],
              ["Model calls", calls],
              ["Conversation cost", usd(stats.cost)],
            ]}
          />
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  )
}

import { FollowupSuggestionsRow } from "@/components/assistant-ui/elements/follow-up-suggestions.aui"
