import type { ThreadMessage, ToolCallMessagePart } from "@assistant-ui/react"

export type ActivityState =
  "running" | "waiting" | "complete" | "error" | "stopped"
export type ActivityItem = {
  id: string
  label: string
  state: ActivityState
  tool: ToolCallMessagePart
}

export const activityLabels: Record<ActivityState, string> = {
  running: "Working",
  waiting: "Needs your input",
  complete: "Complete",
  error: "Needs attention",
  stopped: "Stopped",
}

const names: Record<string, string> = {
  set_plan: "Created a plan",
  update_plan_step: "Updated the plan",
  calculate: "Calculate",
  get_current_time: "Check the time",
  roll_dice: "Roll dice",
  add_note: "Save a note",
  list_notes: "Read notes",
  remove_note: "Remove a note",
  write_document: "Write a document",
  read_document: "Read a document",
  request_input: "Ask a question",
  adk_request_confirmation: "Request approval",
  adk_request_credential: "Request sign-in",
}

export function readResult(value: unknown): Record<string, unknown> {
  if (typeof value === "string") {
    try {
      value = JSON.parse(value)
    } catch {
      return {}
    }
  }
  if (!value || typeof value !== "object" || Array.isArray(value)) return {}
  const result = value as Record<string, unknown>
  return Object.keys(result).length === 1 && "result" in result
    ? readResult(result.result)
    : result
}

export function toolLabel(tool: ToolCallMessagePart) {
  const result = readResult(tool.result)
  if (tool.toolName === "update_plan_step") {
    const step = result.text
    const verb =
      result.status === "done"
        ? "Completed"
        : result.status === "in_progress"
          ? "Started"
          : result.status === "skipped"
            ? "Skipped"
            : "Reopened"
    return typeof step === "string"
      ? `${verb}: ${step}`
      : `Update step ${tool.args.step ?? ""}`.trim()
  }
  const detail =
    tool.args.filename ?? tool.args.expression ?? tool.args.timezone
  const name =
    names[tool.toolName] ??
    tool.toolName.replace(/[_-]+/g, " ").replace(/^./, (c) => c.toUpperCase())
  return typeof detail === "string" ? `${name}: ${detail}` : name
}

/** Project the latest user turn, never infer a successful call from a stopped stream. */
export function activityForTurn(
  messages: readonly ThreadMessage[],
  running: boolean
) {
  const start = messages.findLastIndex((message) => message.role === "user")
  const turn = messages.slice(Math.max(0, start))
  const items: ActivityItem[] = []
  for (const message of turn) {
    if (message.role !== "assistant") continue
    for (const tool of message.content) {
      if (tool.type !== "tool-call") continue
      const result = readResult(tool.result)
      const settled = tool.result !== undefined && !tool.isPreliminary
      const approvalPending =
        tool.approval &&
        tool.approval.approved === undefined &&
        !tool.approval.resolution
      const waiting =
        !settled &&
        (approvalPending ||
          tool.interrupt ||
          message.status.type === "requires-action")
      const state: ActivityState =
        tool.isError || result.error
          ? "error"
          : settled
            ? "complete"
            : waiting
              ? "waiting"
              : running
                ? "running"
                : "stopped"
      items.push({ id: tool.toolCallId, label: toolLabel(tool), state, tool })
    }
  }
  const last = turn.findLast((message) => message.role === "assistant")
  const state: ActivityState =
    items.some((item) => item.state === "waiting") ||
    last?.status?.type === "requires-action"
      ? "waiting"
      : running
        ? "running"
        : last?.status?.type === "incomplete"
          ? last.status.reason === "error"
            ? "error"
            : "stopped"
          : items.some((item) => item.state === "error")
            ? "error"
            : items.some((item) => item.state === "stopped")
              ? "stopped"
              : "complete"
  return {
    items,
    state,
    lastMessageId: last?.id,
    hasMessages: messages.length > 0,
    hasPlanActivity: items.some((item) =>
      ["set_plan", "update_plan_step"].includes(item.tool.toolName)
    ),
    current: items.findLast(
      (item) => item.state === "running" || item.state === "waiting"
    ),
  }
}

import * as React from "react"

/** A tool the agent may use, as the chat API lists it. */
export type AgentTool = {
  /** What a run's `tools` state lists. */
  name: string
  description: string
}

// The tools switched off, so the next visit starts from them. Stored as the
// ones switched off, so a tool the server adds later starts on.
const DISABLED_KEY = "assistant.disabledTools"

function readDisabled(): Set<string> {
  try {
    const saved: unknown = JSON.parse(
      localStorage.getItem(DISABLED_KEY) ?? "[]"
    )
    return new Set(Array.isArray(saved) ? saved.map(String) : [])
  } catch {
    return new Set()
  }
}

function saveDisabled(disabled: Set<string>) {
  try {
    localStorage.setItem(DISABLED_KEY, JSON.stringify([...disabled]))
  } catch {
    // Storage may be unavailable (private mode); the choice lasts the visit.
  }
}

/**
 * The tools the agent at `adkUrl` lets a conversation choose, and which the
 * person has switched on. `enabledNames` is what the next run sends as its
 * `tools` state: undefined until the list arrives, which leaves the agent
 * all of them. Only while `enabled`.
 */
export function useAgentTools(
  adkUrl: string | undefined,
  appName: string,
  enabled: boolean
) {
  const [tools, setTools] = React.useState<AgentTool[]>([])
  const [disabled, setDisabled] = React.useState(readDisabled)

  React.useEffect(() => {
    if (!enabled || !adkUrl) return
    const controller = new AbortController()
    fetch(`${adkUrl}/apps/${encodeURIComponent(appName)}/tools`, {
      signal: controller.signal,
    })
      .then((response) => (response.ok ? response.json() : null))
      .then((body: AgentTool[] | null) => {
        if (body) setTools(body)
      })
      // Without the list the agent keeps all its tools.
      .catch(() => {})
    return () => controller.abort()
  }, [adkUrl, appName, enabled])

  const setToolEnabled = React.useCallback((name: string, on: boolean) => {
    setDisabled((previous) => {
      const next = new Set(previous)
      if (on) next.delete(name)
      else next.add(name)
      saveDisabled(next)
      return next
    })
  }, [])

  const enabledNames = React.useMemo(
    () =>
      tools.length > 0
        ? tools.map((tool) => tool.name).filter((name) => !disabled.has(name))
        : undefined,
    [tools, disabled]
  )

  return { tools, enabledNames, setToolEnabled }
}

import * as React from "react"
import {
  ChatGptIcon,
  ClaudeIcon,
  GoogleGeminiIcon,
} from "@hugeicons/core-free-icons"

import type { AssistantModel } from "@/components/forge/assistant"
import type { IconProp } from "@/components/forge/icons"

/**
 * A model the assistant's conversations may run on, as the chat API's model
 * provider configuration gives it. Nothing about how it's reached.
 */
export type AgentModel = {
  /** provider/model: what a run sends as its `model` state. */
  id: string
  provider: string
  providerName: string
  /** The provider's own id for it. */
  model: string
  name: string
  api: string
  reasoning: boolean
  input: string[]
  contextWindow: number
  maxTokens: number
  /** From least to most thinking: off, minimal, low, medium, high, xhigh. */
  thinkingLevels: string[]
  /** USD per million tokens. */
  cost: { input: number; output: number; cacheRead: number; cacheWrite: number }
}

export type AgentModels = {
  /** What a conversation runs on until it chooses; null when it can't. */
  defaultModel: string | null
  models: AgentModel[]
}

const compact = new Intl.NumberFormat("en", { notation: "compact" })
const noCatalog: AgentModel[] = []

/**
 * The mark of the company that makes a model: by its id first, since a
 * gateway may serve anyone's models over one API, then by the API it speaks.
 */
export function modelMakerIcon(model: AgentModel): IconProp {
  const id = model.model.toLowerCase()
  if (id.startsWith("claude")) return ClaudeIcon
  if (id.startsWith("gemini")) return GoogleGeminiIcon
  if (/^(gpt|o\d|chatgpt|codex)/.test(id)) return ChatGptIcon
  if (model.api === "anthropic-messages") return ClaudeIcon
  if (model.api === "google-generative-ai") return GoogleGeminiIcon
  if (model.api.startsWith("openai-")) return ChatGptIcon
  return "sparkles"
}

/**
 * A model as the composer's model section lists it: under its provider,
 * with its maker's mark.
 */
export function toAssistantModel(model: AgentModel): AssistantModel {
  return {
    id: model.id,
    name: model.name,
    description: `${compact.format(model.contextWindow)} context`,
    group: model.providerName,
    icon: modelMakerIcon(model),
    thinkingLevels: model.thinkingLevels,
  }
}

/**
 * The models the agent at `adkUrl` lets a conversation choose, its default
 * first; none until they arrive, or when the server doesn't say (the
 * assistant then runs on the agent's default). Only while `enabled`.
 */
export function useAssistantModels(
  adkUrl: string | undefined,
  appName: string,
  enabled: boolean
) {
  const [data, setData] = React.useState<AgentModels | null>(null)
  React.useEffect(() => {
    if (!enabled || !adkUrl) return
    const controller = new AbortController()
    fetch(`${adkUrl}/apps/${encodeURIComponent(appName)}/models`, {
      signal: controller.signal,
    })
      .then((response) => (response.ok ? response.json() : null))
      .then((body: AgentModels | null) => {
        if (body) setData(body)
      })
      // The assistant works without them, on the agent's default.
      .catch(() => {})
    return () => controller.abort()
  }, [adkUrl, appName, enabled])
  const models = React.useMemo(
    () => data?.models.map(toAssistantModel) ?? [],
    [data]
  )
  return {
    models,
    defaultModel: data?.defaultModel ?? undefined,
    /** As the server lists them, with context windows and prices. */
    catalog: data?.models ?? noCatalog,
  }
}

