import { useCallback, useEffect, useRef, useState } from "react"

import type { AgentConnection } from "./use-agent-workspace"

export type HistoryEntry = {
  id: string
  title: string
  text: string
  updatedAt: number
}
type Session = {
  id: string
  lastUpdateTime?: number
  events?: {
    author?: string
    content?: { role?: string; parts?: { text?: string; thought?: boolean }[] }
  }[]
}

/** Search visible conversation text; omit model thoughts and raw tool payloads. */
export function historyEntry(session: Session): HistoryEntry {
  const messages = (session.events ?? [])
    .map((event) => ({
      user: event.author === "user" || event.content?.role === "user",
      text: (event.content?.parts ?? [])
        .filter((part) => !part.thought && typeof part.text === "string")
        .map((part) => part.text)
        .join(" ")
        .trim(),
    }))
    .filter((message) => message.text)
  const first = messages
    .find((message) => message.user)
    ?.text.replace(/\s+/g, " ")
  return {
    id: session.id,
    title: first
      ? first.length > 100
        ? `${first.slice(0, 97)}…`
        : first
      : "Untitled chat",
    text: messages.map((message) => message.text).join("\n"),
    updatedAt: session.lastUpdateTime ?? 0,
  }
}

/** The ADK sessions endpoint for a user's conversations. */
const sessionsUrl = ({ adkUrl, appName, userId }: AgentConnection) =>
  adkUrl
    ? `${adkUrl}/apps/${encodeURIComponent(appName)}/users/${encodeURIComponent(userId)}/sessions`
    : undefined

/**
 * The user's conversations, searchable by their text: indexed while `open`,
 * four requests at most at a time, unchanged sessions cached.
 */
export function useChatHistory(open: boolean, connection: AgentConnection) {
  const baseUrl = sessionsUrl(connection)
  const cache = useRef(new Map<string, HistoryEntry>())
  const [entries, setEntries] = useState<HistoryEntry[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [revision, setRevision] = useState(0)
  const retry = useCallback(() => setRevision((value) => value + 1), [])
  useEffect(() => {
    if (!open || !baseUrl) return
    const controller = new AbortController()
    const { signal } = controller
    const read = async (url: string) => {
      const response = await fetch(url, { signal })
      if (!response.ok)
        throw new Error(`History request failed: ${response.status}`)
      return response.json()
    }
    async function load() {
      setLoading(true)
      setError(null)
      try {
        const sessions: Session[] = await read(baseUrl!)
        if (!Array.isArray(sessions))
          throw new Error("Invalid history response")
        const ids = new Set(sessions.map((session) => session.id))
        for (const id of cache.current.keys())
          if (!ids.has(id)) cache.current.delete(id)
        const publish = () => {
          if (!signal.aborted)
            setEntries(
              [...cache.current.values()].sort(
                (a, b) => b.updatedAt - a.updatedAt
              )
            )
        }
        publish()
        const pending = sessions.filter(
          (session) =>
            !cache.current.has(session.id) ||
            !session.lastUpdateTime ||
            cache.current.get(session.id)?.updatedAt !== session.lastUpdateTime
        )
        let failures = 0
        const worker = async () => {
          while (pending.length && !signal.aborted) {
            const session = pending.shift()!
            try {
              const full: Session = await read(
                `${baseUrl}/${encodeURIComponent(session.id)}`
              )
              if (signal.aborted) return
              cache.current.set(
                session.id,
                historyEntry({
                  ...full,
                  id: session.id,
                  lastUpdateTime: session.lastUpdateTime,
                })
              )
              publish()
            } catch {
              if (!signal.aborted) failures += 1
            }
          }
        }
        await Promise.all(
          Array.from({ length: Math.min(4, pending.length) }, worker)
        )
        if (!signal.aborted && failures)
          setError("Some chats couldn’t be searched.")
      } catch {
        if (!signal.aborted) setError("Chat history couldn’t be loaded.")
      } finally {
        if (!signal.aborted) setLoading(false)
      }
    }
    void load()
    return () => controller.abort()
  }, [open, revision, baseUrl])
  return { entries, loading, error, retry }
}

export function matchesHistory(entry: HistoryEntry, query: string) {
  const haystack = `${entry.title}\n${entry.text}`.toLocaleLowerCase()
  return query
    .trim()
    .toLocaleLowerCase()
    .split(/\s+/)
    .every((term) => haystack.includes(term))
}

export function historyExcerpt(entry: HistoryEntry, query: string) {
  if (!query.trim()) return undefined
  const term = query.trim().split(/\s+/)[0].toLocaleLowerCase()
  const index = entry.text.toLocaleLowerCase().indexOf(term)
  if (index < 0) return undefined
  const start = Math.max(0, index - 35)
  const excerpt = entry.text.slice(start, start + 130).replace(/\s+/g, " ")
  return `${start ? "…" : ""}${excerpt}${entry.text.length > start + 130 ? "…" : ""}`
}

import * as React from "react"
import { useAuiState } from "@assistant-ui/react"
import { useAdkLongRunningToolIds } from "@assistant-ui/react-google-adk"
import { create } from "zustand"

type FollowUpsState = {
  /** By reply: its suggestions, or "loading" while they're written. */
  byReply: Record<string, string[] | "loading">
  set: (replyId: string, value: string[] | "loading") => void
}

const useFollowUpsStore = create<FollowUpsState>((set) => ({
  byReply: {},
  set: (replyId, value) =>
    set((state) => ({ byReply: { ...state.byReply, [replyId]: value } })),
}))

/**
 * Follow-up questions for the conversation's last reply, from the chat API
 * (`POST …/sessions/{id}/follow-ups`): asked once the reply is done, unless
 * the agent is waiting on the person (an approval or a question), and kept
 * per reply for the visit. Empty until they arrive.
 */
export function useFollowUps(
  adkUrl: string | undefined,
  appName: string,
  userId: string
): string[] {
  const sessionId = useAuiState((s) => s.threadListItem.remoteId)
  const running = useAuiState((s) => s.thread.isRunning)
  const lastReply = useAuiState((s) => {
    const last = s.thread.messages.at(-1)
    return last?.role === "assistant" ? last.id : undefined
  })
  const waiting = useAdkLongRunningToolIds().length > 0
  const cached = useFollowUpsStore((state) =>
    lastReply ? state.byReply[lastReply] : undefined
  )
  const set = useFollowUpsStore((state) => state.set)

  React.useEffect(() => {
    if (!adkUrl || !sessionId || !lastReply || running || waiting) return
    if (useFollowUpsStore.getState().byReply[lastReply] !== undefined) return
    set(lastReply, "loading")
    const url = `${adkUrl}/apps/${encodeURIComponent(appName)}/users/${encodeURIComponent(userId)}/sessions/${encodeURIComponent(sessionId)}/follow-ups`
    fetch(url, { method: "POST" })
      .then((response) => (response.ok ? response.json() : { suggestions: [] }))
      .then((body: { suggestions?: string[] }) =>
        set(lastReply, body.suggestions ?? [])
      )
      .catch(() => set(lastReply, []))
  }, [adkUrl, appName, userId, sessionId, lastReply, running, waiting, set])

  return !running && !waiting && Array.isArray(cached) ? cached : []
}

const compact = new Intl.NumberFormat("en", {
  notation: "compact",
  maximumFractionDigits: 1,
})
const whole = new Intl.NumberFormat("en")

/** 845, 12.4k, 1.2M. */
export const tokens = (count: number) => compact.format(count)

/** 12,345. */
export const exactTokens = (count: number) => whole.format(count)

/** 0.8s, 12s, 1m 5s. */
export function duration(seconds: number) {
  if (seconds < 10) return `${seconds.toFixed(1)}s`
  if (seconds < 60) return `${Math.round(seconds)}s`
  return `${Math.floor(seconds / 60)}m ${Math.round(seconds % 60)}s`
}

/** $0.0004, $0.12, $3.40; "<$0.0001" for a fraction of that. */
export function usd(amount: number) {
  if (amount === 0) return "$0"
  if (amount < 0.0001) return "<$0.0001"
  if (amount < 0.01) return `$${amount.toPrecision(2)}`
  return `$${amount.toFixed(2)}`
}

import { useAdkSessionState } from "@assistant-ui/react-google-adk"

export type Note = { id: string; text: string }

/**
 * The open conversation's notes, which its agent keeps in the session state
 * `notes` (adk_chat.builtin_tools). Updates as each change streams in.
 */
export function useNotes(): Note[] {
  const state = useAdkSessionState()
  return Array.isArray(state.notes) ? (state.notes as Note[]) : []
}

import { create } from "zustand"

/** The side panels the screen can show beside the chat, one at a time. */
export type Panel = "notes" | "plan" | "canvas"

type ScreenState = {
  /** The panel showing beside the chat; null for none. */
  panel: Panel | null
  openPanel: (panel: Panel) => void
  closePanel: () => void
  togglePanel: (panel: Panel) => void
  /** Progress strips dismissed in this browser session, keyed by response. */
  dismissedProgress: readonly string[]
  dismissProgress: (id: string) => void
}

/**
 * What the screen shows around the chat. Tool UIs change it when their calls
 * finish (`useToolFinished`), e.g. opening the notes panel after `add_note`;
 * the top bar's buttons change it too.
 */
export const useScreen = create<ScreenState>((set) => ({
  panel: null,
  dismissedProgress: [],
  dismissProgress: (id) =>
    set((state) => ({
      dismissedProgress: [
        ...state.dismissedProgress.filter((key) => key !== id).slice(-99),
        id,
      ],
    })),
  openPanel: (panel) => set({ panel }),
  closePanel: () => set({ panel: null }),
  togglePanel: (panel) =>
    set((state) => ({ panel: state.panel === panel ? null : panel })),
}))

const isObject = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value)

/**
 * A tool's result as the object it returned. ADK results arrive as values or
 * JSON text, sometimes wrapped as `{ result }`.
 */
export function toolResult<T extends object>(result: unknown): Partial<T> {
  let value = result
  if (typeof value === "string") {
    try {
      value = JSON.parse(value)
    } catch {
      return {}
    }
  }
  if (
    isObject(value) &&
    isObject(value.result) &&
    Object.keys(value).length === 1
  )
    value = value.result
  return isObject(value) ? (value as Partial<T>) : {}
}

import * as React from "react"
import { useAuiState } from "@assistant-ui/react"
import { create } from "zustand"

import type { AgentModel } from "./assistant-models"

/** One turn's cost: every model call its agent made, summed. */
export type TurnStats = {
  /** Seconds from the person's message to the last event. */
  seconds: number
  calls: number
  inputTokens: number
  outputTokens: number
  /** Of the output tokens, those spent reasoning. */
  reasoningTokens: number
  cachedTokens: number
  /** USD, from the model's prices; 0 when it has none. */
  cost: number
  /** False when any model call has no configured price. */
  costKnown: boolean
  /** provider/model, as the conversation had it chosen. */
  model: string | undefined
  thinkingLevel: string | undefined
}

export type ConversationStats = {
  sessionId: string
  /** By ADK invocation: one per message the person sent. */
  turns: Record<string, TurnStats>
  /** Each event's invocation, to find a reply's turn from its id. */
  eventTurn: Record<string, string>
  /** The last model call's input + output: how full the context is. */
  contextTokens: number
  /** The model that call ran on. */
  contextModel: string | undefined
  cost: number
}

type Usage = {
  promptTokenCount?: number
  candidatesTokenCount?: number
  thoughtsTokenCount?: number
  cachedContentTokenCount?: number
}

type StoredEvent = {
  id: string
  invocationId?: string
  timestamp: number
  usageMetadata?: Usage
  actions?: { stateDelta?: Record<string, unknown> }
}

const perMillion = 1_000_000

/**
 * A conversation's stats from its stored ADK events: each model call's usage,
 * summed per invocation, priced with the model the conversation had chosen
 * at that point (its `model` state), else the agent's default.
 */
export function conversationStats(
  sessionId: string,
  events: StoredEvent[],
  catalog: AgentModel[],
  defaultModel: string | undefined
): ConversationStats {
  const prices = new Map(catalog.map((model) => [model.id, model.cost]))
  const turns: Record<string, TurnStats & { start: number; end: number }> = {}
  const eventTurn: Record<string, string> = {}
  let model = defaultModel
  let thinkingLevel: string | undefined
  let contextTokens = 0
  let contextModel: string | undefined
  let cost = 0

  for (const event of events) {
    const delta = event.actions?.stateDelta ?? {}
    if (typeof delta.model === "string" && delta.model) model = delta.model
    if (typeof delta.thinking_level === "string")
      thinkingLevel = delta.thinking_level
    const turnId = event.invocationId
    if (!turnId) continue
    eventTurn[event.id] = turnId
    const turn = (turns[turnId] ??= {
      seconds: 0,
      calls: 0,
      inputTokens: 0,
      outputTokens: 0,
      reasoningTokens: 0,
      cachedTokens: 0,
      cost: 0,
      costKnown: true,
      model,
      thinkingLevel,
      start: event.timestamp,
      end: event.timestamp,
    })
    turn.start = Math.min(turn.start, event.timestamp)
    turn.end = Math.max(turn.end, event.timestamp)
    turn.seconds = turn.end - turn.start
    const usage = event.usageMetadata
    if (!usage) continue
    const input = usage.promptTokenCount ?? 0
    const output = usage.candidatesTokenCount ?? 0
    const cached = usage.cachedContentTokenCount ?? 0
    const price = model ? prices.get(model) : undefined
    if (!price) turn.costKnown = false
    const callCost = price
      ? ((input - cached) * price.input +
          cached * price.cacheRead +
          output * price.output) /
        perMillion
      : 0
    turn.calls += 1
    turn.inputTokens += input
    turn.outputTokens += output
    turn.reasoningTokens += usage.thoughtsTokenCount ?? 0
    turn.cachedTokens += cached
    turn.cost += callCost
    cost += callCost
    contextTokens = input + output
    contextModel = model
  }
  return { sessionId, turns, eventTurn, contextTokens, contextModel, cost }
}

type TurnStatsState = {
  stats: ConversationStats | null
  /** Replaced when a conversation's events are read. */
  setStats: (stats: ConversationStats | null) => void
}

/** The open conversation's stats, for message footers and the meter. */
export const useTurnStats = create<TurnStatsState>((set) => ({
  stats: null,
  setStats: (stats) => set({ stats }),
}))

/**
 * Keeps `useTurnStats` on the open conversation: reads its stored events
 * when it opens and after each reply finishes. Render it once, inside the
 * assistant's providers.
 */
export function useTurnStatsSync(
  adkUrl: string | undefined,
  appName: string,
  userId: string,
  catalog: AgentModel[],
  defaultModel: string | undefined
) {
  const sessionId = useAuiState((s) => s.threadListItem.remoteId)
  const running = useAuiState((s) => s.thread.isRunning)
  const setStats = useTurnStats((state) => state.setStats)
  React.useEffect(() => {
    // Read after the reply, not during it: stored events are final.
    if (!adkUrl || !sessionId || running) {
      if (!sessionId) setStats(null)
      return
    }
    const controller = new AbortController()
    const url = `${adkUrl}/apps/${encodeURIComponent(appName)}/users/${encodeURIComponent(userId)}/sessions/${encodeURIComponent(sessionId)}`
    fetch(url, { signal: controller.signal })
      .then((response) => (response.ok ? response.json() : null))
      .then((session: { events?: StoredEvent[] } | null) => {
        if (session?.events)
          setStats(
            conversationStats(sessionId, session.events, catalog, defaultModel)
          )
      })
      .catch(() => {})
    return () => controller.abort()
  }, [
    adkUrl,
    appName,
    userId,
    sessionId,
    running,
    catalog,
    defaultModel,
    setStats,
  ])
}

/** The ADK event a reply's message id names: `<eventId>:ai[n]`. */
export const eventIdOf = (messageId: string) => messageId.split(":")[0]

import { useMemo } from "react"
import { useAuiState } from "@assistant-ui/react"
import { activityForTurn } from "./activity"
import { eventIdOf, useTurnStats } from "./turn-stats"

export function useAgentActivity() {
  const messages = useAuiState((s) => s.thread.messages)
  const running = useAuiState((s) => s.thread.isRunning)
  const sessionId = useAuiState((s) => s.threadListItem.remoteId)
  const stats = useTurnStats((s) => s.stats)
  const activity = useMemo(
    () => activityForTurn(messages, running),
    [messages, running]
  )
  const turnId =
    stats && stats.sessionId === sessionId && activity.lastMessageId
      ? stats.eventTurn[eventIdOf(activity.lastMessageId)]
      : undefined
  const turn = !running && turnId ? stats?.turns[turnId] : undefined
  return { ...activity, running, sessionId, turn }
}

import * as React from "react"
import type { AdkStreamCallback } from "@assistant-ui/react-google-adk"

import {
  extendedThinkingLevels,
  useAdkAssistant,
  type AssistantFeedback,
  type ModelSettings,
} from "@/components/forge/assistant"
import { ChatAttachmentAdapter } from "@/lib/attachments"

import { useAgentTools } from "./agent-tools"
import { useAssistantModels } from "./assistant-models"

/** Where the agent is: what every connected workspace part takes. */
export type AgentConnection = {
  /**
   * An ADK API server (`adk api_server`), or the chat API's `/agents`, which
   * serves its agent in the same protocol. Undefined: not connected.
   */
  adkUrl: string | undefined
  /** The agent's app name on the server. */
  appName: string
  /** Whose conversations these are; the server keeps each user's apart. */
  userId: string
}

export type AgentWorkspaceOptions = AgentConnection & {
  /**
   * The server is the chat API (adk-chat), which also lists the agent's
   * models (`/apps/{app}/models`) and tools (`/apps/{app}/tools`) and stores
   * 👍/👎 feedback. Leave it off for a plain ADK API server.
   */
  chatApi?: boolean
  /** The assistant's reply while `adkUrl` is undefined. */
  notConnectedMessage?: string
}

/**
 * The composer's model section, for the assistant's props: shown while the
 * agent offers models.
 */
export type ModelSection =
  { showModels: true; modelSettings: ModelSettings } | { showModels: false }

// Images, PDFs and text files on messages (the composer's + button). One
// object, so the runtime isn't rebuilt on every render.
const ADAPTERS = { attachments: new ChatAttachmentAdapter() }

const DEFAULT_NOT_CONNECTED =
  "The agent isn't connected yet. Point the app at an ADK agent server " +
  "(`adkUrl`) and reload."

// The model section's last choices, so the next visit starts from them.
const MODEL_KEY = "assistant.model"
const THINKING_KEY = "assistant.thinkingLevel"

function readSaved(key: string): string {
  try {
    return localStorage.getItem(key) ?? ""
  } catch {
    return ""
  }
}

function save(key: string, value: string) {
  try {
    localStorage.setItem(key, value)
  } catch {
    // Storage may be unavailable (private mode); the choice lasts the visit.
  }
}

/** Saves a 👍/👎 on a reply with the chat API, by session and message. */
async function saveFeedback(
  { adkUrl, appName, userId }: AgentConnection,
  feedback: AssistantFeedback
) {
  if (!adkUrl || !feedback.sessionId) return
  const url = `${adkUrl}/apps/${encodeURIComponent(appName)}/users/${encodeURIComponent(userId)}/sessions/${encodeURIComponent(feedback.sessionId)}/feedback`
  const response = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      messageId: feedback.message.id,
      rating: feedback.type,
      text: feedback.text,
      comment: feedback.comment,
    }),
  })
  if (!response.ok) console.warn("Couldn't save feedback", response.status)
}

function useSavedModelSettings(settings: ModelSettings): ModelSettings {
  return React.useMemo(
    () => ({
      ...settings,
      setModel: (id: string) => {
        settings.setModel(id)
        save(MODEL_KEY, id)
      },
      setThinkingLevel: (id: string) => {
        settings.setThinkingLevel(id)
        save(THINKING_KEY, id)
      },
    }),
    [settings]
  )
}

/**
 * The assistant for an ADK agent, with the workspace's extras: the models
 * and tools the chat API offers (remembered between visits), attachments,
 * and 👍/👎 feedback. Spread `modelSection` into `AssistantScreen`; pass
 * `tools` to `ToolsMenu` and `catalog` / `defaultModel` to `ContextMeter`.
 *
 * ```tsx
 * const agent = useAgentWorkspace({ adkUrl, appName: "assistant", userId, chatApi: true })
 * <AssistantScreen runtime={agent.runtime} artifacts={agent.artifacts} {...agent.modelSection} />
 * ```
 */
export function useAgentWorkspace({
  adkUrl,
  appName,
  userId,
  chatApi = false,
  notConnectedMessage = DEFAULT_NOT_CONNECTED,
}: AgentWorkspaceOptions) {
  const serverLists = chatApi && Boolean(adkUrl) && Boolean(userId)
  // The models the agent may run on, its default first.
  const { models, defaultModel, catalog } = useAssistantModels(
    adkUrl,
    appName,
    serverLists
  )
  // The tools it may use, and which are switched on.
  const tools = useAgentTools(adkUrl, appName, serverLists)
  const { enabledNames } = tools
  const [savedModel] = React.useState(() => readSaved(MODEL_KEY))
  const [savedLevel] = React.useState(() => readSaved(THINKING_KEY))

  const notConnected = React.useMemo<AdkStreamCallback>(
    () =>
      async function* () {
        yield {
          id: crypto.randomUUID(),
          author: appName,
          content: { role: "model", parts: [{ text: notConnectedMessage }] },
          turnComplete: true,
        }
      },
    [appName, notConnectedMessage]
  )

  const { runtime, artifacts, modelSettings } = useAdkAssistant(
    adkUrl
      ? {
          // ADK keeps each user's conversations apart by this ID.
          adk: { url: adkUrl, appName, userId },
          // The tools switched on, as the run's `tools` state; left out (all
          // of them) until the list arrives.
          runState: () => ({ tools: enabledNames }),
          adapters: ADAPTERS,
          // Shows 👍/👎 on replies; the chat API saves each rating.
          ...(chatApi && {
            onFeedback: (feedback: AssistantFeedback) =>
              saveFeedback({ adkUrl, appName, userId }, feedback),
          }),
          // Sent as the run's `model` and `thinking_level` state while the
          // model section shows. A saved model that's gone falls back to the
          // first, the agent's default.
          models,
          defaultModel: savedModel || defaultModel,
          thinkingLevels: extendedThinkingLevels,
          defaultThinkingLevel: savedLevel || undefined,
        }
      : { stream: notConnected }
  )
  const saved = useSavedModelSettings(modelSettings)
  const modelSection: ModelSection =
    adkUrl && models.length > 0
      ? { showModels: true, modelSettings: saved }
      : { showModels: false }
  return {
    runtime,
    artifacts,
    modelSection,
    tools,
    /** The models as the server lists them, with context windows and prices. */
    catalog,
    defaultModel,
    /** An agent server is configured; without one it explains how to connect. */
    connected: adkUrl !== undefined,
  }
}

import * as React from "react"
import type { ToolCallMessagePartStatus } from "@assistant-ui/react"

/**
 * Calls `onFinish` once when a tool call this page watched running finishes
 * successfully: for a tool UI to change the screen (`useScreen`) or refresh
 * a section. A call that was already done when it rendered, e.g. in a past
 * conversation being opened, doesn't call it, so replaying history leaves the
 * screen alone.
 */
export function useToolFinished(
  status: ToolCallMessagePartStatus,
  onFinish: () => void
) {
  const sawRunning = React.useRef(status.type === "running")
  const onFinishRef = React.useRef(onFinish)
  React.useEffect(() => {
    onFinishRef.current = onFinish
  })
  React.useEffect(() => {
    if (status.type === "running") {
      sawRunning.current = true
    } else if (status.type === "complete" && sawRunning.current) {
      sawRunning.current = false
      onFinishRef.current()
    }
  }, [status.type])
}

/**
 * Calls `onDone` once when a call this page saw waiting for the person's
 * approval (ADK `require_confirmation`) is approved and its result arrives,
 * the counterpart of `useToolFinished` for a gated tool, which doesn't show
 * as running while it waits. A call already decided when it rendered doesn't
 * call it.
 */
export function useToolApproved(
  part: {
    approval?: { approved?: boolean } | undefined
    result?: unknown
  },
  isDone: (result: unknown) => boolean,
  onDone: () => void
) {
  const approved = part.approval?.approved
  const done = approved === true && isDone(part.result)
  const sawWaiting = React.useRef(
    part.approval !== undefined && approved === undefined
  )
  const onDoneRef = React.useRef(onDone)
  React.useEffect(() => {
    onDoneRef.current = onDone
  })
  React.useEffect(() => {
    if (part.approval !== undefined && approved === undefined) {
      sawWaiting.current = true
    } else if (done && sawWaiting.current) {
      sawWaiting.current = false
      onDoneRef.current()
    }
  }, [part.approval, approved, done])
}

import { Note01Icon } from "@hugeicons/core-free-icons"

import { PanelButton, SidePanel } from "./side-panel"
