import { CheckListIcon } from "@hugeicons/core-free-icons"
import { ActivityMark } from "./activity-mark"
import { Icon } from "@/components/forge/icon"
import { PlanSteps } from "./plan-steps"
import { PanelButton, SidePanel } from "./side-panel"
import { TurnDetails } from "./turn-details"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { activityLabels, type ActivityItem } from "./lib/activity"
import { finishedSteps, usePlan } from "./lib/plan"
import { useAgentActivity } from "./lib/use-agent-activity"

export function PlanPanel() {
  const plan = usePlan()
  const activity = useAgentActivity()
  const done = plan ? finishedSteps(plan) : 0
  const total = plan?.steps.length ?? 0
  const completed =
    plan?.steps.filter((step) => step.status === "done").length ?? 0
  const skipped =
    plan?.steps.filter((step) => step.status === "skipped").length ?? 0
  return (
    <SidePanel
      panel="plan"
      title="Task details"
      icon={CheckListIcon}
      className="w-80 xl:w-[352px]"
    >
      <Tabs
        key={activity.sessionId ?? "new"}
        defaultValue={plan ? "plan" : "activity"}
        className="min-h-0 flex-1 gap-0"
      >
        <div className="border-b px-4 pt-2">
          <TabsList variant="line" className="w-full justify-start gap-5">
            <TabsTrigger value="plan" className="flex-none px-0 pb-2 text-xs">
              Plan
              {total > 0 && (
                <span className="font-normal text-muted-foreground tabular-nums">
                  {done}/{total}
                </span>
              )}
            </TabsTrigger>
            <TabsTrigger
              value="activity"
              className="flex-none px-0 pb-2 text-xs"
            >
              Activity
              <span className="font-normal text-muted-foreground tabular-nums">
                {activity.items.length}
              </span>
            </TabsTrigger>
          </TabsList>
        </div>
        <TabsContent value="plan" className="min-h-0 overflow-y-auto p-4">
          {!plan ? (
            <EmptyDetail
              title="Room for a plan"
              description="For work with several steps, the assistant will lay out a plan here and update it as it goes."
            />
          ) : (
            <>
              <p className="mb-2 text-2xs font-medium tracking-wide text-muted-foreground uppercase">
                Latest plan
              </p>
              <h3 className="text-base leading-snug font-medium text-foreground">
                {plan.title}
              </h3>
              <div className="mt-3 mb-5 flex items-center gap-2 text-xs text-muted-foreground">
                <Icon icon={done === total ? "completed" : "task"} size={14} />
                <span>
                  {completed} completed
                  {skipped > 0 ? `, ${skipped} skipped` : ""}
                </span>
                <span className="ml-auto tabular-nums">
                  {done} of {total}
                </span>
              </div>
              <PlanSteps
                plan={plan}
                detailed
                live={activity.running && activity.hasPlanActivity}
              />
              {done < total && !activity.running && (
                <p className="mt-5 border-t pt-3 text-xs leading-relaxed text-muted-foreground">
                  {activity.state === "waiting"
                    ? "Answer the request in the conversation to continue."
                    : "This plan has unfinished steps. Send a message to continue or change direction."}
                </p>
              )}
            </>
          )}
        </TabsContent>
        <TabsContent value="activity" className="min-h-0 overflow-y-auto p-4">
          <div className="mb-5 flex items-center gap-2.5">
            <ActivityMark state={activity.state} />
            <div>
              <h3 className="text-sm font-medium">
                {activityLabels[activity.state]}
              </h3>
              <p className="mt-0.5 text-2xs text-muted-foreground">
                Latest response
              </p>
            </div>
          </div>
          {activity.items.length === 0 ? (
            <EmptyDetail
              title={
                activity.running
                  ? "The assistant is working"
                  : "No tool activity"
              }
              description={
                activity.running
                  ? "Tool actions will appear here as they happen."
                  : "This response did not use any tools."
              }
            />
          ) : (
            <ol className="divide-y divide-border/70">
              {activity.items.map((item) => (
                <ActivityRow key={item.id} item={item} />
              ))}
            </ol>
          )}
          {activity.turn && activity.turn.calls > 0 && (
            <section className="mt-6 border-t pt-4">
              <h3 className="mb-3 text-xs font-medium">Response statistics</h3>
              <TurnDetails turn={activity.turn} />
            </section>
          )}
          {activity.running && (
            <p className="mt-5 text-2xs leading-relaxed text-muted-foreground">
              Usage and cost appear after the response finishes.
            </p>
          )}
        </TabsContent>
      </Tabs>
    </SidePanel>
  )
}

function EmptyDetail({
  title,
  description,
}: {
  title: string
  description: string
}) {
  return (
    <div className="py-6">
      <Icon icon="list" size={22} className="mb-3 text-muted-foreground" />
      <h3 className="text-sm font-medium">{title}</h3>
      <p className="mt-2 max-w-[32ch] text-xs leading-relaxed text-muted-foreground">
        {description}
      </p>
    </div>
  )
}

function ActivityRow({ item }: { item: ActivityItem }) {
  return (
    <li className="py-1">
      <details className="group">
        <summary className="flex cursor-pointer list-none items-start gap-2.5 rounded-md py-2.5 text-xs [&::-webkit-details-marker]:hidden">
          <ActivityMark state={item.state} />
          <span className="min-w-0 flex-1">
            <span className="block leading-relaxed wrap-anywhere text-foreground">
              {item.label}
            </span>
            <span className="mt-0.5 block text-2xs text-muted-foreground">
              {activityLabels[item.state]}
            </span>
          </span>
          <Icon
            icon="right"
            size={13}
            className="mt-1 text-muted-foreground transition-transform group-open:rotate-90"
          />
        </summary>
        <div className="mb-3 space-y-3 rounded-md bg-muted/50 p-3">
          <p className="font-mono text-2xs wrap-anywhere text-muted-foreground">
            {item.tool.toolName}
          </p>
          <RawDetail label="Input" value={item.tool.args} />
          {item.tool.result !== undefined && (
            <RawDetail label="Result" value={item.tool.result} />
          )}
          {item.state === "waiting" && (
            <p className="text-xs text-muted-foreground">
              Respond to the request in the conversation.
            </p>
          )}
          {item.state === "stopped" && (
            <p className="text-xs text-muted-foreground">
              No result was received for this action.
            </p>
          )}
        </div>
      </details>
    </li>
  )
}

function RawDetail({ label, value }: { label: string; value: unknown }) {
  return (
    <div>
      <p className="mb-1 text-2xs font-medium text-muted-foreground">{label}</p>
      <pre className="max-h-52 overflow-auto font-mono text-2xs leading-relaxed wrap-anywhere whitespace-pre-wrap">
        {typeof value === "string" ? value : JSON.stringify(value, null, 2)}
      </pre>
    </div>
  )
}

export function PlanButton() {
  const plan = usePlan()
  const { hasMessages } = useAgentActivity()
  if (!plan && !hasMessages) return null
  return (
    <PanelButton
      panel="plan"
      label="Task details"
      icon={CheckListIcon}
      badge={plan ? `${finishedSteps(plan)}/${plan.steps.length}` : "Activity"}
    />
  )
}

import { useAuiState } from "@assistant-ui/react"
import { MinusSignIcon, Tick02Icon } from "@hugeicons/core-free-icons"
import { cn } from "cn"

import { Icon } from "@/components/forge/icon"
import { Spinner } from "@/components/ui/spinner"
import type { Plan, StepStatus } from "./lib/plan"
import { duration } from "./lib/format"

/**
 * A step's mark: an empty ring, a started one (a ring with a dot, spinning
 * only while `live`: the agent is working on it now), a green tick or a dash.
 */
export function StepMark({
  status,
  live = false,
}: {
  status: StepStatus
  live?: boolean
}) {
  if (status === "in_progress" && live)
    return <Spinner className="size-4 shrink-0 text-foreground" />
  if (status === "in_progress")
    return (
      <span className="flex size-4 shrink-0 items-center justify-center rounded-full ring-1 ring-foreground/40 ring-inset">
        <span className="size-1.5 rounded-full bg-foreground/70" />
      </span>
    )
  return (
    <span
      className={cn(
        "flex size-4 shrink-0 items-center justify-center rounded-full transition-colors duration-300",
        status === "done" &&
          "bg-success-surface text-success-foreground ring-1 ring-success-border",
        status === "skipped" && "bg-muted text-muted-foreground",
        status === "pending" && "ring-1 ring-border ring-inset"
      )}
    >
      {status === "done" && <Icon icon={Tick02Icon} size={10} />}
      {status === "skipped" && <Icon icon={MinusSignIcon} size={10} />}
    </span>
  )
}

/**
 * The plan's steps as a checklist, numbered, the current one highlighted; it
 * spins only while a reply is running, so a step the agent left started
 * doesn't spin after it's done.
 */
export function PlanSteps({
  plan,
  detailed = false,
  live,
}: {
  plan: Plan
  detailed?: boolean
  live?: boolean
}) {
  const threadRunning = useAuiState((s) => s.thread.isRunning)
  const running = live ?? threadRunning
  return (
    <ol className="flex flex-col gap-0.5">
      {plan.steps.map((step, index) => (
        <li
          key={index}
          className={cn(
            "flex items-start gap-2.5 rounded-md px-2 py-2.5 text-sm transition-colors duration-200",
            step.status === "in_progress" && "bg-muted"
          )}
        >
          <span className="mt-0.5">
            <StepMark status={step.status} live={running} />
          </span>
          <span
            className={cn(
              "min-w-0 flex-1 leading-snug",
              step.status === "done" && "text-muted-foreground",
              step.status === "skipped" &&
                "text-muted-foreground line-through decoration-muted-foreground/50",
              step.status === "in_progress" && "font-medium text-foreground"
            )}
          >
            <span className="me-1.5 text-2xs text-muted-foreground tabular-nums">
              {index + 1}.
            </span>
            {step.text}
            {!detailed && (
              <span className="sr-only">
                {" "}
                (
                {step.status === "done"
                  ? "Completed"
                  : step.status === "skipped"
                    ? "Skipped"
                    : step.status === "in_progress"
                      ? running
                        ? "In progress"
                        : "Unfinished"
                      : "Not started"}
                )
              </span>
            )}
            {detailed && (
              <span className="mt-1.5 flex items-center gap-2 text-2xs font-normal text-muted-foreground no-underline">
                <span>
                  {step.status === "done"
                    ? "Completed"
                    : step.status === "skipped"
                      ? "Skipped"
                      : step.status === "in_progress"
                        ? running
                          ? "In progress"
                          : "Unfinished"
                        : "Not started"}
                </span>
                {step.started_at != null &&
                  step.finished_at != null &&
                  step.finished_at >= step.started_at && (
                    <>
                      <span aria-hidden>·</span>
                      <span className="tabular-nums">
                        {duration(step.finished_at - step.started_at)} elapsed
                      </span>
                    </>
                  )}
              </span>
            )}
          </span>
        </li>
      ))}
    </ol>
  )
}

import { useId, useState } from "react"
import { useAuiState } from "@assistant-ui/react"
import { TooltipIconButton } from "@/components/assistant-ui/elements/tooltip-icon-button"
import { ActivityMark } from "./activity-mark"
import { Icon } from "@/components/forge/icon"
import { PlanSteps } from "./plan-steps"
import { activityLabels } from "./lib/activity"
import { finishedSteps, usePlan } from "./lib/plan"
import { useScreen } from "./lib/screen-store"
import { useAgentActivity } from "./lib/use-agent-activity"
import { cn } from "cn"

/** Show progress only when the current turn has an agent-created task list. */
export function ProgressDock() {
  const activity = useAgentActivity()
  const plan = usePlan()
  const userMessageId = useAuiState(
    (s) => s.thread.messages.findLast((message) => message.role === "user")?.id
  )
  const progressId = `${activity.sessionId ?? "new"}:${userMessageId ?? "empty"}`
  const dismissed = useScreen((s) => s.dismissedProgress.includes(progressId))
  const dismissProgress = useScreen((s) => s.dismissProgress)
  if (dismissed) return null
  return (
    <ProgressDockContent
      key={progressId}
      activity={activity}
      plan={plan}
      onDismiss={() => dismissProgress(progressId)}
    />
  )
}

function ProgressDockContent({
  activity,
  plan,
  onDismiss,
}: {
  activity: ReturnType<typeof useAgentActivity>
  plan: ReturnType<typeof usePlan>
  onDismiss: () => void
}) {
  const [expanded, setExpanded] = useState(false)
  const id = useId()
  const openPanel = useScreen((s) => s.openPanel)
  const relevantPlan = activity.hasPlanActivity ? plan : null
  // Ordinary replies and tool calls stay in the conversation. A saved plan
  // from an earlier turn must not make this panel appear again.
  if (!relevantPlan) return null
  const done = relevantPlan ? finishedSteps(relevantPlan) : 0
  const total = relevantPlan?.steps.length ?? 0
  const activeStep = relevantPlan?.steps.find(
    (step) => step.status === "in_progress"
  )
  const title =
    activity.state === "waiting"
      ? "Your input is needed to continue"
      : activity.state === "error"
        ? "There’s an issue to review"
        : activity.state === "stopped"
          ? "Work stopped. Your progress is saved."
          : activity.running
            ? (activeStep?.text ??
              activity.current?.label ??
              "Working on your request")
            : relevantPlan
              ? relevantPlan.title
              : "Finished this response"
  const label =
    relevantPlan &&
    !activity.running &&
    done < total &&
    activity.state === "complete"
      ? "Plan unfinished"
      : relevantPlan && done === total && activity.state === "complete"
        ? "Plan finished"
        : activityLabels[activity.state]
  const markState = label === "Plan unfinished" ? "stopped" : activity.state
  return (
    <section
      aria-label="Task progress"
      className="overflow-hidden rounded-xl border border-border bg-muted/25"
    >
      <div className="flex items-center gap-1 px-1">
        <button
          type="button"
          aria-expanded={relevantPlan ? expanded : undefined}
          aria-controls={relevantPlan ? id : undefined}
          onClick={() =>
            relevantPlan ? setExpanded(!expanded) : openPanel("plan")
          }
          className="flex min-w-0 flex-1 items-center gap-3 rounded-lg px-2.5 py-3 text-start transition-colors hover:bg-muted/70"
        >
          <ActivityMark state={markState} />
          <span className="min-w-0 flex-1">
            <span className="mb-0.5 block text-2xs text-muted-foreground">
              {label}
            </span>
            <span className="block truncate text-xs font-medium" title={title}>
              {title}
            </span>
          </span>
          {total > 0 && (
            <span className="shrink-0 text-2xs text-muted-foreground tabular-nums">
              {done} / {total}
            </span>
          )}
          <Icon
            icon={relevantPlan ? "up" : "right"}
            size={14}
            className={cn(
              "shrink-0 text-muted-foreground transition-transform duration-200",
              relevantPlan && !expanded && "rotate-180"
            )}
          />
        </button>
        <button
          type="button"
          onClick={() => openPanel("plan")}
          aria-label="Open task details"
          className="flex size-8 shrink-0 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
        >
          <Icon icon="sidebar" size={16} />
        </button>
        <TooltipIconButton
          tooltip="Dismiss task progress"
          className="mr-1 size-8 shrink-0 rounded-md text-muted-foreground hover:bg-muted hover:text-foreground"
          onClick={(event) => {
            // Return keyboard focus to the nearby composer before removing
            // the focused dismiss control from the document.
            event.currentTarget
              .closest(".aui-thread-viewport-footer")
              ?.querySelector<HTMLTextAreaElement>(
                'textarea[aria-label="Message input"]'
              )
              ?.focus()
            onDismiss()
          }}
        >
          <Icon icon="close" size={14} />
        </TooltipIconButton>
      </div>
      {relevantPlan && (
        <div id={id} hidden={!expanded} className="border-t px-2 py-2">
          <div className="max-h-[min(32dvh,18rem)] overflow-y-auto">
            <PlanSteps
              plan={relevantPlan}
              live={activity.running && activity.hasPlanActivity}
            />
          </div>
          <button
            type="button"
            onClick={() => openPanel("plan")}
            className="mt-1 flex w-full items-center justify-between rounded-md px-2 py-2 text-xs text-muted-foreground hover:bg-muted hover:text-foreground"
          >
            <span>View activity and details</span>
            <Icon icon="right" size={14} />
          </button>
        </div>
      )}
      {total > 0 && (
        <div
          role="progressbar"
          aria-label="Plan progress"
          aria-valuenow={done}
          aria-valuemin={0}
          aria-valuemax={total}
          aria-valuetext={`${done} of ${total} steps resolved`}
          className="h-0.5 bg-border/60"
        >
          <div
            className="h-full origin-left bg-foreground/50 transition-transform duration-200 ease-out"
            style={{ transform: `scaleX(${done / total})` }}
          />
        </div>
      )}
    </section>
  )
}

import type * as React from "react"
import { useSyncExternalStore } from "react"
import { Cancel01Icon } from "@hugeicons/core-free-icons"
import { cn } from "cn"

import { TooltipIconButton } from "@/components/assistant-ui/elements/tooltip-icon-button"
import { Icon } from "@/components/forge/icon"
import type { IconProp } from "@/components/forge/icons"
import { useScreen, type Panel } from "./lib/screen-store"
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from "@/components/ui/sheet"

const subscribeNarrow = (listener: () => void) => {
  const query = window.matchMedia("(max-width: 767px)")
  query.addEventListener("change", listener)
  return () => query.removeEventListener("change", listener)
}
const isNarrow = () => window.matchMedia("(max-width: 767px)").matches

/**
 * A panel beside the chat, shown while `useScreen`'s panel is `panel`: a
 * titled header with a close button, and `children` scrolling below. Render
 * it inside `AssistantScreen` (its `aside`), so it can read the session.
 */
export function SidePanel({
  panel,
  title,
  icon,
  actions,
  className,
  children,
}: {
  panel: Panel
  title: React.ReactNode
  icon: IconProp
  /** Header controls before the close button. */
  actions?: React.ReactNode
  className?: string
  children: React.ReactNode
}) {
  const open = useScreen((state) => state.panel === panel)
  const closePanel = useScreen((state) => state.closePanel)
  const narrow = useSyncExternalStore(subscribeNarrow, isNarrow, () => false)
  if (narrow)
    return (
      <Sheet
        open={open}
        onOpenChange={(next) => {
          if (!next) closePanel()
        }}
      >
        <SheetContent className="data-[side=right]:w-[calc(100%-24px)] data-[side=right]:sm:max-w-sm">
          <SheetHeader className="border-b pr-14">
            <SheetTitle>{title}</SheetTitle>
            <SheetDescription className="sr-only">
              Details for this conversation.
            </SheetDescription>
          </SheetHeader>
          <div className="flex min-h-0 flex-1 flex-col">{children}</div>
        </SheetContent>
      </Sheet>
    )
  if (!open) return null
  return (
    <aside
      aria-label={typeof title === "string" ? title : panel}
      data-panel={panel}
      className={cn(
        "flex w-72 shrink-0 animate-in flex-col border-s bg-sidebar duration-200 fade-in slide-in-from-right-4",
        className
      )}
    >
      <header className="flex h-12 shrink-0 items-center gap-2 border-b px-4">
        <Icon
          icon={icon}
          size={15}
          className="shrink-0 text-muted-foreground"
        />
        <h2 className="min-w-0 flex-1 truncate text-sm font-medium">{title}</h2>
        {actions}
        <TooltipIconButton
          tooltip="Close"
          side="bottom"
          className="size-7 rounded-md p-0 text-muted-foreground hover:text-foreground"
          onClick={closePanel}
        >
          <Icon icon={Cancel01Icon} size={14} />
        </TooltipIconButton>
      </header>
      <div className="flex min-h-0 flex-1 flex-col">{children}</div>
    </aside>
  )
}

/** In the top bar: shows or hides a side panel, with an optional count. */
export function PanelButton({
  panel,
  label,
  icon,
  badge,
}: {
  panel: Panel
  label: string
  icon: IconProp
  badge?: React.ReactNode
}) {
  const open = useScreen((state) => state.panel === panel)
  const togglePanel = useScreen((state) => state.togglePanel)
  return (
    <TooltipIconButton
      tooltip={
        open ? `Hide ${label.toLowerCase()}` : `Show ${label.toLowerCase()}`
      }
      side="bottom"
      aria-pressed={open}
      className="h-7 w-auto gap-1.5 rounded-md px-2 text-xs text-muted-foreground hover:text-foreground aria-pressed:bg-muted aria-pressed:text-foreground"
      onClick={() => togglePanel(panel)}
    >
      <Icon icon={icon} size={15} />
      {badge !== undefined && <span className="tabular-nums">{badge}</span>}
    </TooltipIconButton>
  )
}

