import type { ToolCallMessagePartComponent } from "@assistant-ui/react"

import { StepMark } from "../plan-steps"
import type { Plan, StepStatus } from "../lib/plan"
import { toolResult } from "../lib/tool-result"

import { ToolFrame } from "./tool-frame"

export const SetPlanUI: ToolCallMessagePartComponent<{
  title: string
  steps: string[]
}> = (part) => {
  const { plan, error } = toolResult<{ plan: Plan; error: string }>(part.result)
  const steps = plan?.steps.length ?? part.args.steps?.length ?? 0
  return (
    <ToolFrame
      part={part}
      running={<>Planning</>}
      label={
        error ? (
          <>Couldn't make a plan: {error}</>
        ) : (
          <>
            Planned <b>{part.args.title}</b>: {steps} steps
          </>
        )
      }
    />
  )
}

type StepResult = {
  step: number
  text: string
  status: StepStatus
  done: number
  total: number
  error: string
}

const VERBS: Record<StepStatus, string> = {
  in_progress: "Started",
  done: "Finished",
  skipped: "Skipped",
  pending: "Reopened",
}

export const UpdatePlanStepUI: ToolCallMessagePartComponent<{
  step: number
  status: StepStatus
}> = (part) => {
  const result = toolResult<StepResult>(part.result)
  if (result.error)
    return <ToolFrame part={part} running={null} label={<>{result.error}</>} />
  // Successful status changes live in the plan and Activity view; avoid
  // repeating every transition in the conversation. Errors remain inline.
  if (part.status.type === "complete" && result.status) return null
  return (
    <ToolFrame
      part={part}
      running={<>Updating the plan</>}
      label={
        <span className="flex items-center gap-2">
          {/* What the call did, not what's happening now: never spins. */}
          {result.status && <StepMark status={result.status} />}
          <span>
            {VERBS[part.args.status] ?? "Updated"} step {part.args.step}
            {result.text && <>: {result.text}</>}
          </span>
          {result.total ? (
            <span className="text-muted-foreground/70 tabular-nums">
              {result.done}/{result.total}
            </span>
          ) : null}
        </span>
      }
    />
  )
}

import type * as React from "react"
import type { ToolCallMessagePartProps } from "@assistant-ui/react"

import { ToolFallback } from "@/components/assistant-ui/elements/tool-fallback.aui"

/**
 * A tool call's card in the conversation: the standard line (spinner and
 * shimmer while it runs, the call's args and raw result when opened), labelled
 * with what the call did, and `children` below it once it's done, e.g. dice
 * or a clock. A failed or cancelled call keeps its label, with the standard
 * cross (and the error when opened).
 */
export function ToolFrame({
  part,
  label,
  running,
  children,
}: {
  part: ToolCallMessagePartProps
  /** What it did, once it's done. */
  label: React.ReactNode
  /** What it's doing, while it runs. */
  running: React.ReactNode
  children?: React.ReactNode
}) {
  const { toolName, status, argsText, result } = part
  const done = status.type === "complete"
  return (
    <div data-slot="tool-ui" className="flex flex-col gap-1.5">
      <ToolFallback.Root>
        <ToolFallback.Trigger
          toolName={toolName}
          status={status}
          label={
            done || status.type === "incomplete"
              ? label
              : status.type === "running"
                ? running
                : undefined
          }
        />
        <ToolFallback.Content>
          <ToolFallback.Error status={status} />
          <ToolFallback.Args argsText={argsText} />
          <ToolFallback.Result result={result} />
        </ToolFallback.Content>
      </ToolFallback.Root>
      {done && children}
    </div>
  )
}

